          const taxPct = Math.max(0, Math.min(100, Number(body.taxPct) || 0));
          const subtotal = Number(body.subtotal) || items.reduce((a, it) => a + it.qty * it.amount, 0);
          const grandTotal = Number(body.grandTotal) || (subtotal * (1 - discountPct / 100) * (1 + taxPct / 100));
